  const selectCollectionBranch=branch=>{if(branch.officialLatitude!=null&&branch.officialLongitude!=null||branch.hasPendingGps||branch.temporaryGpsStatus==='pending_supervisor')return fail(t('gpsCollection.alreadyRecorded'));setSearch(formatBranchId(branch.branchId));setBranches([branch]);setBranchId(String(branch.branchId));setGps({...emptyGpsCapture,address:branch.address||''});setBranchInUrl(branch.branchId);requestAnimationFrame(()=>formRef.current?.scrollIntoView({behavior:'smooth',block:'start'}))}
  const clearSelectedBranch=()=>{setSearch('');setBranches([]);setBranchId('');setGps(emptyGpsCapture);setBranchInUrl('')}
  useEffect(()=>{if(search.length<2)return setBranches([]);const timer=setTimeout(()=>api(`/api/master/branches?search=${encodeURIComponent(search)}&pageSize=20`).then(data=>setBranches(data.items)).catch(item=>fail(item.message)),250);return()=>clearTimeout(timer)},[search,fail]);useEffect(()=>{void loadQueue();void loadCollection()},[reload,loadQueue,loadCollection])
  useEffect(()=>{if(selectedBranch?.address)setGps(current=>current.address?current:{...current,address:selectedBranch.address})},[selectedBranch?.branchId,selectedBranch?.address])
